using System;using System.Linq;using System.Net;using System.Net.Sockets;using System.Diagnostics;using System.Threading;
namespace ServiceTool{internal static class ServiceEndpointTests{
[STAThread]static int Main(){try{uint pid=(uint)Process.GetCurrentProcess().Id;foreach(var ip in new[]{IPAddress.Loopback,IPAddress.IPv6Loopback}){var server=new TcpListener(ip,0);server.Start();try{int port=((IPEndPoint)server.LocalEndpoint).Port;if(!ServiceEndpoints.Listeners(pid).Any(l=>l.Port==port&&l.Pid==pid))throw new Exception("Native PID/port mismatch "+ip);}finally{server.Stop();}}Console.WriteLine("PASS native IPv4/IPv6 listeners linked to exact PID");var info=ServiceEndpoints.Inspect("DK.Banking.Agent");Console.WriteLine(info.Summary);if(info.Checks.Count>0){foreach(var url in info.Checks){if(!ServiceEndpoints.StillOwns("DK.Banking.Agent",url))throw new Exception("Ownership lost");var result=ServiceProbe.Check(url,CancellationToken.None);if(!result.Message.Contains("Служба отвечает"))throw new Exception(result.Message);Console.WriteLine("PASS discovered Banking address -> HTTP200 Pong: "+url);}}else throw new Exception("Banking automatic profile not discovered on current host");var stopped=ServiceEndpoints.Inspect("DK.Fiscalization.Agent.Atol");if(stopped.Pid==0&&stopped.Checks.Count!=0)throw new Exception("Stopped service has check URL");Console.WriteLine("PASS stopped-service read, no start operation");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}}
